  flaechenverlustMaxKat1: 0.1,
  flaechenverlustMaxKat2: 0.15,
  /** DIN SPEC 91434: landwirtschaftlicher Ertrag mind. 66 % des Referenzertrags */
  mindestErtrag: 0.66,
